import re
import time

from ansible.module_utils._text import to_native


def _sysctl_path(module):
    path = module.get_bin_path('sysctl')
    if not path:
        raise ValueError('sysctl binary not found')
    return path


def get_sysctl(module, prefixes):
    try:
        cmd = [_sysctl_path(module)] + list(prefixes)
        rc, out, err = module.run_command(cmd)
    except (IOError, OSError) as e:
        module.warn('Unable to read sysctl: %s' % to_native(e))
        return {}
    if rc != 0:
        module.warn('Unable to read sysctl: %s' % (err.strip() or 'exit status %s' % rc))
        return {}

    sysctl = {}
    previous_key = None
    for line in out.splitlines():
        if not line:
            if previous_key is not None:
                sysctl[previous_key] += '\n'
            continue
        if line[0].isspace():
            if previous_key is not None:
                sysctl[previous_key] += '\n' + line
            else:
                module.warn('Unable to split sysctl line (%s): no preceding key' % line)
            continue
        try:
            key, value = re.split(r'\s*=\s*|:\s*|\s+', line, maxsplit=1)
            if not key or not value:
                raise ValueError('missing key or value')
        except ValueError as e:
            module.warn('Unable to split sysctl line (%s): %s' % (line, to_native(e)))
            previous_key = None
            continue
        sysctl[key] = value.strip()
        previous_key = key

    return sysctl


def _get_uptime_facts(module):
    try:
        rc, out, err = module.run_command([_sysctl_path(module), '-n', 'kern.boottime'])
    except (IOError, OSError) as e:
        if getattr(e, 'errno', None) == errno.ENOENT:
            raise ValueError('sysctl binary not found')
        module.warn('Unable to read sysctl: %s' % to_native(e))
        return {}
    if rc != 0:
        module.warn('Unable to read sysctl: %s' % (err.strip() or 'exit status %s' % rc))
        return {}
    value = out.strip()
    if not value:
        return {}
    try:
        boot_time = int(value)
    except ValueError:
        module.warn('Unable to parse sysctl kern.boottime: %s' % value)
        return {}
    return {'uptime_seconds': int(time.time() - boot_time)}
